for k,(v,L) in P.items(): assert len(L)==len(KEYS),(k,len(L))
VOICES = {}
for k,(v,L) in P.items(): VOICES.setdefault(v,[]).append(k)
if __name__=='__main__':
    import json,sys
    if sys.argv[1:]==['tts']:
        for v,ks in VOICES.items():
            txt='\n'.join(l for k in ks for l in P[k][1]); print(v,len(txt)); print(txt); print('=====')
    else: print(json.dumps({'keys':KEYS,'p':{k:{'v':v,'l':L} for k,(v,L) in P.items()}},ensure_ascii=False))
